#!/usr/bin/env bash
# Compile the prototype effect Metal presets (ios/prototype-agent/Shaders/PrototypeEffects.metal) and
# emit a Swift source that embeds the metallib as base64 bytes (#15130). SwiftPM does not compile
# .metal files, the injectable dylib has no bundle for a .metallib resource, and ShaderLibrary loads
# only precompiled libraries, so the agent and the viewers compile the generated file with the rest of
# their sources and load it with ShaderLibrary(data:). The metallib is built every time and never
# committed, which keeps binary files out of git.
#
# Usage: scripts/ios/prototype-effects-metallib.sh <output-dir>
# Prints the path of the generated PrototypeEffectsMetallib.swift. Env:
#   PROTOTYPE_AGENT_MIN_IOS   deployment target of the shader (default 17.0)
#   PROTOTYPE_EFFECTS_SOURCE  override the .metal file (tests)
#   PROTOTYPE_EFFECTS_NO_DOWNLOAD=1  fail instead of downloading the Metal Toolchain
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
source_file="${PROTOTYPE_EFFECTS_SOURCE:-${repo_root}/ios/prototype-agent/Shaders/PrototypeEffects.metal}"
out_dir="${1:?usage: prototype-effects-metallib.sh <output-dir>}"
min_ios="${PROTOTYPE_AGENT_MIN_IOS:-17.0}"
mkdir -p "${out_dir}"

# Since Xcode 26 the Metal Toolchain is a separate component; CI installs it here on first use.
if ! xcrun --sdk iphonesimulator metal --version > /dev/null 2>&1; then
  if [[ "${PROTOTYPE_EFFECTS_NO_DOWNLOAD:-}" == 1 ]]; then
    echo "The Metal Toolchain is not installed (xcodebuild -downloadComponent metalToolchain)" >&2
    exit 1
  fi
  xcodebuild -downloadComponent metalToolchain >&2
fi

air="${out_dir}/PrototypeEffects.air"
metallib="${out_dir}/PrototypeEffects.metallib"
xcrun --sdk iphonesimulator metal -c -std=metal3.1 "-mios-simulator-version-min=${min_ios}" \
  "${source_file}" -o "${air}"
xcrun --sdk iphonesimulator metallib "${air}" -o "${metallib}"

generated="${out_dir}/PrototypeEffectsMetallib.swift"
{
  echo "// Generated by scripts/ios/prototype-effects-metallib.sh; do not edit or commit."
  echo "enum PrototypeEffectsMetallib {"
  printf '    static let base64 = "'
  base64 < "${metallib}" | tr -d '\n'
  echo '"'
  echo "}"
} > "${generated}"
echo "${generated}"
